    body {
      font-family: system-ui, -apple-system, sans-serif;
      font-size: 13px;
      background: #000000;
      color: #ccc;
      height: 100vh;
      display: flex;
      flex-direction: column;
      overflow: hidden;
    }
 
    /* ── Top bar ── */
    #topbar {
      padding: 6px 12px;
      font-size: 14px;
      color: #ddd;
      flex-shrink: 0;
      border-bottom: 1px solid #333;
      background: #000000;
    }
 
    /* ── Main layout ── */
    #main {
      display: flex;
      flex: 1;
      overflow: hidden;
    }
 
    /* ── Viewport area ── */
    #viewport-wrap {
      flex: 1;
      position: relative;
      overflow: hidden;
    }
 
    #canvas-0 {
      width: 100%;
      height: 100%;
      display: block;
    }
 
    .drop-hint {
      position: absolute;
      bottom: 14px;
      left: 50%;
      transform: translateX(-50%);
      font-size: 12px;
      color: rgba(255,255,255,0.25);
      pointer-events: none;
    }
 
    /* 3 color-picker squares top-right of viewport */
    #color-pickers {
      position: absolute;
      top: 10px;
      right: 10px;
      display: flex;
      flex-direction: column;
      gap: 5px;
    }
 
    #color-pickers input[type="color"] {
      width: 30px;
      height: 28px;
      border: none;
      border-radius: 3px;
      background: #444;
      cursor: pointer;
      padding: 2px;
    }
 
    /* ── Right panel ── */
    #right-panel {
      width: 220px;
      flex-shrink: 0;
      display: flex;
      flex-direction: column;
      gap: 8px;
      padding: 8px;
      background: #262626;
      overflow-y: auto;
    }
 
    .panel-box {
      background: #000000;
      border-radius: 8px;
      overflow: hidden;
    }
 
    .panel-box .panel-title {
      text-align: center;
      font-size: 12px;
      color: #ebebeb;
      padding: 5px 0 4px;
      border-bottom: 1px solid #2e2e2e;
    }
 
    .panel-body {
      padding: 8px;
    }
 
    /* ── Position panel ── */
    .pos-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 4px;
    }
 
    .pos-grid input[type="number"] {
      width: 100%;
      background: #333;
      border: none;
      border-radius: 3px;
      color: #ccc;
      font-size: 11px;
      padding: 4px 5px;
      text-align: center;
      outline: none;
    }
 
    .pos-grid input[type="number"]:focus {
      background: #3e3e3e;
    }
 
    /* ── Light panel ── */
    .light-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 6px;
      font-size: 12px;
      color: #aaa;
    }
 
    .light-row input[type="range"] {
      flex: 1;
      margin-left: 8px;
      accent-color: #888;
      height: 4px;
    }
 
    .light-color-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 4px;
      margin-top: 4px;
    }
 
    .light-color-row input[type="color"] {
      width: 100%;
      height: 26px;
      border: none;
      border-radius: 3px;
      background: #333;
      cursor: pointer;
      padding: 2px;
    }
 
    /* ── Polygon panel ── */
    .poly-table {
      width: 100%;
      border-collapse: collapse;
    }
 
    .poly-table td {
      padding: 3px 6px;
      font-size: 12px;
      color: #aaa;
    }
 
    .poly-table td:nth-child(2),
    .poly-table td:nth-child(3) {
      text-align: right;
      color: #888;
      width: 36px;
    }
 
    /* ── Bottom bar ── */
    #bottombar {
      flex-shrink: 0;
      padding: 8px 12px;
      border-top: 1px solid #333;
      display: flex;
      align-items: center;
      gap: 10px;
      background: #000000;
    }
 
    #browse-btn {
      background: #00000000;
      color: #ccc;
      border: 1px solid #ffffff;
      border-radius: 6px;
      padding: 6px 16px;
      font-size: 13px;
      cursor: pointer;
    }
 
    #browse-btn:hover { background: #aeaeae; }
 
